"use client";

import { useEffect, useRef } from "react";
import { useVelocityState } from "./VelocityContext";

export const SpeedLines: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const { normalizedVelocity } = useVelocityState();
  const velocityRef = useRef(normalizedVelocity);
  const particlesRef = useRef<
    { x: number; y: number; length: number; speed: number }[]
  >([]);

  useEffect(() => {
    velocityRef.current = normalizedVelocity;
  }, [normalizedVelocity]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }

    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }

    let animationFrameId: number;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const particleCount = 40;
    if (particlesRef.current.length === 0) {
      for (let i = 0; i < particleCount; i++) {
        particlesRef.current.push({
          x: Math.random() * width,
          y: Math.random() * height,
          length: Math.random() * 100 + 50,
          speed: Math.random() * 5 + 2,
        });
      }
    }

    const draw = () => {
      const v = velocityRef.current;
      ctx.clearRect(0, 0, width, height);

      if (v < 0.1) {
        animationFrameId = requestAnimationFrame(draw);
        return;
      }

      const centerX = width / 2;
      const centerY = height / 2;

      particlesRef.current.forEach((p) => {
        const distanceX = p.x - centerX;
        const distanceY = p.y - centerY;
        const angle = Math.atan2(distanceY, distanceX);
        const distance = Math.sqrt(
          distanceX * distanceX + distanceY * distanceY
        );

        // Opacity based on velocity and distance from center
        const opacity = v * 0.5 * (distance / (width / 2));
        ctx.strokeStyle = `rgba(255, 255, 255, ${opacity})`;
        ctx.lineWidth = 0.5 + v * 1.5;

        ctx.beginPath();
        ctx.moveTo(p.x, p.y);

        // Line length increases with velocity and distance from center
        const lineLength = p.length * v * (distance / (width / 2));
        const endX = p.x + Math.cos(angle) * lineLength;
        const endY = p.y + Math.sin(angle) * lineLength;

        ctx.lineTo(endX, endY);
        ctx.stroke();

        // Move particles away from center
        const speed = p.speed * v * 20;
        p.x += Math.cos(angle) * speed;
        p.y += Math.sin(angle) * speed;

        // Reset particles if they go off screen
        if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) {
          const startAngle = Math.random() * Math.PI * 2;
          const startDistance = Math.random() * 200;
          p.x = centerX + Math.cos(startAngle) * startDistance;
          p.y = centerY + Math.sin(startAngle) * startDistance;
          p.length = Math.random() * 80 + 20;
        }
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    const handleResize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };

    window.addEventListener("resize", handleResize);
    animationFrameId = requestAnimationFrame(draw);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  return (
    <canvas
      className="pointer-events-none fixed inset-0 z-0 opacity-40 mix-blend-screen"
      ref={canvasRef}
    />
  );
};

"use client";

import { useScroll, useSpring, useVelocity } from "motion/react";
import React, { createContext, useContext, useEffect, useState } from "react";
import { SPRING_CONFIGS, TIMINGS, VELOCITY_THRESHOLDS } from "./constants";

type ReadingState = "detailed" | "skim";

interface VelocityContextType {
  isScrolling: boolean;
  lockVelocity: () => void;
  manualVelocity: number | null;
  normalizedVelocity: number; // 0 to 1
  readingState: ReadingState;
  setManualVelocity: (v: number | null) => void;
  velocity: number;
}

const VelocityContext = createContext<VelocityContextType | undefined>(
  undefined
);

export const VelocityProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const { scrollY } = useScroll();
  const scrollVelocity = useVelocity(scrollY);

  // Use a spring to smooth out the velocity values for UI transitions
  const smoothVelocity = useSpring(
    scrollVelocity,
    SPRING_CONFIGS.VELOCITY_SMOOTHING
  );

  const [scrollV, setScrollV] = useState(0);
  const [manualVelocity, setManualVelocity] = useState<number | null>(null);
  const [readingState, setReadingState] = useState<ReadingState>("detailed");
  const [isVelocityLocked, setIsVelocityLocked] = useState(false);

  // Use a ref to manage the exit timer identity
  const exitTimerRef = React.useRef<NodeJS.Timeout | null>(null);

  // Unified logic to update reading state based on current velocity
  const updateReadingState = React.useCallback((v: number) => {
    // Clear timer if we exceed skim entrance threshold
    if (v > VELOCITY_THRESHOLDS.SKIM_ENTER) {
      setReadingState("skim");
      if (exitTimerRef.current) {
        clearTimeout(exitTimerRef.current);
        exitTimerRef.current = null;
      }
    }
    // Start or continue exit timer if below exit threshold
    else if (v < VELOCITY_THRESHOLDS.SKIM_EXIT) {
      setReadingState((prev) => {
        if (prev === "skim" && !exitTimerRef.current) {
          exitTimerRef.current = setTimeout(() => {
            setReadingState("detailed");
            exitTimerRef.current = null;
          }, TIMINGS.SKIM_EXIT_DELAY);
        }
        return prev;
      });
    }
    // Intermediate zone: cancel exit timer if user speeds up slightly
    else if (
      v >= VELOCITY_THRESHOLDS.SKIM_EXIT &&
      v <= VELOCITY_THRESHOLDS.SKIM_ENTER &&
      exitTimerRef.current
    ) {
      clearTimeout(exitTimerRef.current);
      exitTimerRef.current = null;
    }
  }, []);

  // effectiveVelocity is either manual override or scroll velocity
  const velocity = manualVelocity !== null ? manualVelocity : scrollV;

  useEffect(() => {
    const unsubscribe = smoothVelocity.on("change", (v) => {
      if (isVelocityLocked) {
        return;
      }
      const absV = Math.floor(Math.abs(v));
      if (absV !== Math.floor(scrollV)) {
        setScrollV(absV);

        // Update reading state based on new scroll velocity (only if manual override is OFF)
        if (manualVelocity === null) {
          updateReadingState(absV);
        }
      }
    });

    return () => unsubscribe();
  }, [
    smoothVelocity,
    scrollV,
    isVelocityLocked,
    manualVelocity,
    updateReadingState,
  ]);

  const lockVelocity = React.useCallback(() => {
    setIsVelocityLocked(true);
    // Neutralize the underlying MotionValues to prevent the spring from "momentum-swallowing" the spike
    scrollVelocity.set(0);
    smoothVelocity.set(0);

    if (exitTimerRef.current) {
      clearTimeout(exitTimerRef.current);
      exitTimerRef.current = null;
    }

    // A slightly longer lock ensures the browser and framer-motion have fully settled
    setTimeout(
      () => setIsVelocityLocked(false),
      TIMINGS.SCROLL_LOCK_DURATION + 100
    );
  }, [scrollVelocity, smoothVelocity]);

  const handleSetManualVelocity = React.useCallback(
    (v: number | null) => {
      setManualVelocity(v);
      if (v !== null) {
        updateReadingState(v);
      }
    },
    [updateReadingState]
  );

  useEffect(() => {
    const unsubscribe = scrollY.on("change", (latest) => {
      if (latest <= 0) {
        updateReadingState(0);
      }
    });
    return () => unsubscribe();
  }, [scrollY, updateReadingState]);

  // Optimize derived values and context object
  const normalizedVelocity = React.useMemo(
    () => Math.min(velocity / VELOCITY_THRESHOLDS.NORMALIZATION_MAX, 1),
    [velocity]
  );

  const isScrolling = React.useMemo(
    () =>
      velocity > VELOCITY_THRESHOLDS.IS_SCROLLING || manualVelocity !== null,
    [velocity, manualVelocity]
  );

  const contextValue = React.useMemo(
    () => ({
      velocity,
      normalizedVelocity,
      readingState,
      isScrolling,
      manualVelocity,
      setManualVelocity: handleSetManualVelocity,
      lockVelocity,
    }),
    [
      velocity,
      normalizedVelocity,
      readingState,
      isScrolling,
      manualVelocity,
      handleSetManualVelocity,
      lockVelocity,
    ]
  );

  return (
    <VelocityContext.Provider value={contextValue}>
      {children}
    </VelocityContext.Provider>
  );
};

export const useVelocityState = () => {
  const context = useContext(VelocityContext);
  if (context === undefined) {
    throw new Error("useVelocityState must be used within a VelocityProvider");
  }
  return context;
};

/**
 * Velocity-Responsive Design (VRD) Constants
 */

export const VELOCITY_THRESHOLDS = {
  SKIM_ENTER: 2500, // Transition to skim mode at 2500 px/s
  SKIM_EXIT: 400, // Must drop below 400 px/s to trigger exit countdown
  IS_SCROLLING: 10,
  NORMALIZATION_MAX: 3000, // Visual effects scale relative to this peak
};

export const TIMINGS = {
  SKIM_EXIT_DELAY: 2500, // Duration to stay in skim mode after speed drops
  SCROLL_LOCK_DURATION: 350, // Duration to lock velocity tracking during programmatic scrolls
};

export const SPRING_CONFIGS = {
  VELOCITY_SMOOTHING: {
    damping: 50,
    stiffness: 400,
  },
  TRANSITION: {
    duration: 0.6,
    type: "spring" as const,
    damping: 30,
    stiffness: 100,
  },
  IMAGE_TRANSITION: {
    type: "spring" as const,
    damping: 30,
    stiffness: 150,
  },
  IMAGE_MOTION: {
    type: "spring" as const,
    damping: 25,
    stiffness: 120,
    mass: 0.5,
  },
};

"use client";

import { FileCode, Terminal } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import type React from "react";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityCodeBlockProps {
  code: string;
  filename: string;
  language: string;
}

export const VelocityCodeBlock: React.FC<VelocityCodeBlockProps> = ({
  filename,
  language,
  code,
}) => {
  const { readingState } = useVelocityState();
  const isSkim = readingState === "skim";

  return (
    <motion.div
      animate={{
        scale: isSkim ? 0.98 : 1,
        opacity: isSkim ? 0.8 : 1,
      }}
      className={`my-8 overflow-hidden rounded-lg border ${
        isSkim
          ? "border-primary/20 bg-primary/5"
          : "border-white/10 bg-zinc-950"
      }`}
      layout
      transition={SPRING_CONFIGS.TRANSITION}
    >
      <div className="flex items-center justify-between border-white/5 border-b bg-white/5 px-4 py-2">
        <div className="flex items-center gap-2">
          <FileCode className="text-primary" size={14} />
          <span className="font-mono text-muted-foreground text-xs">
            {filename}
          </span>
        </div>
        <span className="text-[10px] text-muted-foreground/50 uppercase tracking-widest">
          {language}
        </span>
      </div>

      <AnimatePresence initial={false} mode="popLayout">
        {isSkim ? (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className="relative flex h-10 items-center gap-3 overflow-hidden px-4 text-primary/60 text-sm italic"
            exit={{ opacity: 0, scale: 0.98 }}
            initial={{ opacity: 0, scale: 1.02 }}
            key="skim"
          >
            <motion.div
              animate={{ x: ["-100%", "200%"] }}
              className="pointer-events-none absolute inset-0 bg-linear-to-r from-transparent via-primary/5 to-transparent"
              transition={{
                duration: 1.5,
                repeat: Number.POSITIVE_INFINITY,
                ease: "linear",
              }}
            />
            <Terminal size={14} />
            <span>Implementation details collapsed for speed...</span>
          </motion.div>
        ) : (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className="overflow-x-auto p-4"
            exit={{ opacity: 0, scale: 1.02 }}
            initial={{ opacity: 0, scale: 0.98 }}
            key="detailed"
          >
            <pre className="font-mono text-sm text-zinc-300">
              <code>{code}</code>
            </pre>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

"use client";

import { AlertCircle, ImageIcon } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import type React from "react";
import { useState } from "react";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityImageProps {
  alt: string;
  src: string;
}

export const VelocityImage: React.FC<VelocityImageProps> = ({ src, alt }) => {
  const { normalizedVelocity, readingState } = useVelocityState();
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  const isSkim = readingState === "skim";

  const opacity = 0.8 + (1 - normalizedVelocity) * 0.2;

  return (
    <motion.div
      animate={{
        height: isSkim ? "auto" : 0,
        opacity: isSkim ? 1 : 0,
        marginBottom: isSkim ? 80 : 0,
        marginTop: isSkim ? 80 : 0,
        pointerEvents: isSkim ? "auto" : "none",
      }}
      className="relative w-full overflow-hidden px-4 sm:px-0"
      initial={false}
      layout="position"
      transition={SPRING_CONFIGS.IMAGE_TRANSITION}
    >
      <motion.div
        animate={{
          opacity,
          y: isSkim ? -normalizedVelocity * 20 : 0,
        }}
        className="relative z-10 flex aspect-video min-h-[200px] items-center justify-center overflow-hidden rounded-2xl border border-white/10 bg-zinc-900 shadow-[0_0_50px_rgba(0,0,0,0.5)] sm:min-h-[300px]"
        style={{
          transformOrigin: "center center",
        }}
        transition={SPRING_CONFIGS.IMAGE_MOTION}
      >
        <AnimatePresence mode="wait">
          {/* Only render image if we are skimming or transitioning */}
          {(isSkim || normalizedVelocity > 0.1) && !error ? (
            <motion.div
              animate={{ opacity: 1 }}
              className="relative h-full w-full"
              exit={{ opacity: 0 }}
              initial={{ opacity: 0 }}
              key="content"
            >
              {loading ? (
                <div className="absolute inset-0 flex items-center justify-center text-zinc-800">
                  <ImageIcon
                    className="animate-pulse"
                    size={48}
                    strokeWidth={1}
                  />
                </div>
              ) : null}
              <motion.img
                alt={alt}
                className="block h-full w-full object-cover"
                onError={() => setError(true)}
                onLoad={() => setLoading(false)}
                src={src}
                transition={{ duration: 0.5 }}
              />
            </motion.div>
          ) : null}

          {error ? (
            <motion.div
              animate={{ opacity: 1 }}
              className="flex flex-col items-center gap-2 text-zinc-600"
              initial={{ opacity: 0 }}
              key="error"
            >
              <AlertCircle size={40} strokeWidth={1} />
              <span className="font-mono text-xs uppercase tracking-widest">
                {alt} (Load Failed)
              </span>
            </motion.div>
          ) : null}
        </AnimatePresence>

        <motion.div
          animate={{
            background:
              isSkim && !error
                ? `linear-gradient(to bottom, rgba(0,0,0,${normalizedVelocity * 0.3}), transparent)`
                : "rgba(0,0,0,0)",
          }}
          className="pointer-events-none absolute inset-0"
        />

        {/* Subtle highlight instead of blur */}
        {normalizedVelocity > 0.4 && !error ? (
          <motion.div
            className="pointer-events-none absolute inset-0 bg-white/5 mix-blend-overlay"
            style={{
              opacity: (normalizedVelocity - 0.4) * 1.5,
            }}
          />
        ) : null}
      </motion.div>

      <motion.div
        animate={{
          opacity: isSkim && !error ? normalizedVelocity * 0.3 : 0,
        }}
        className="absolute inset-0 -z-10 rounded-full bg-primary/20 blur-[100px]"
      />
    </motion.div>
  );
};

"use client";

import { Monitor, Settings, Zap } from "lucide-react";
import { motion } from "motion/react";
import type React from "react";
import { useEffect, useLayoutEffect, useRef } from "react";
import { AIWidget } from "@/components/ui/AIWidget";
import { VELOCITY_THRESHOLDS } from "./constants";
import { CONTENT } from "./content";
import { SpeedLines } from "./SpeedLines";
import { VelocityCodeBlock } from "./VelocityCodeBlock";
import { useVelocityState, VelocityProvider } from "./VelocityContext";
import { VelocityImage } from "./VelocityImage";
import { VelocityText } from "./VelocityText";

const StaticBackgroundPattern = () => (
  <div
    className="pointer-events-none absolute inset-0 opacity-20"
    style={{
      backgroundImage:
        "radial-gradient(circle at 2px 2px, rgba(255,255,255,0.05) 1px, transparent 0)",
      backgroundSize: "40px 40px",
    }}
  />
);

function FlightControl() {
  const { velocity, manualVelocity, setManualVelocity, readingState } =
    useVelocityState();

  return (
    <div className="fixed bottom-8 left-1/2 z-100 flex w-[calc(100%-2rem)] max-w-[420px] -translate-x-1/2 items-center gap-3 rounded-2xl border border-white/10 bg-zinc-900/60 p-3 shadow-[0_20px_50px_rgba(0,0,0,0.5)] backdrop-blur-2xl sm:gap-6 sm:p-4">
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        <div className="mb-1 flex justify-between font-mono text-[9px] text-zinc-500 uppercase tracking-widest sm:text-[10px]">
          <span className="flex items-center gap-1.5 truncate sm:gap-2">
            <Zap
              className={
                manualVelocity !== null
                  ? "animate-pulse text-primary"
                  : "text-primary/50"
              }
              size={10}
            />
            <span className="hidden min-[400px]:inline">Velocity Vector</span>
            <span className="min-[400px]:hidden">VEL</span>
          </span>
          <span
            className={
              readingState === "skim"
                ? "whitespace-nowrap font-bold text-primary"
                : "whitespace-nowrap text-zinc-400"
            }
          >
            {Math.round(velocity)} PX/S
          </span>
        </div>

        {/* Enhanced Slider Container */}
        <div className="group/slider relative flex h-8 w-full items-center">
          {/* Visual Track Background */}
          <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-zinc-800/50">
            {/* Progressive Fill */}
            <motion.div
              animate={{
                width: `${Math.min((velocity / VELOCITY_THRESHOLDS.NORMALIZATION_MAX) * 100, 100)}%`,
                backgroundColor:
                  manualVelocity !== null ? "#3b82f6" : "#ffffff", // Primary color or white
              }}
              className="absolute inset-y-0 left-0 bg-primary/80"
              transition={{ type: "spring", damping: 30, stiffness: 200 }}
            />
          </div>

          {/* Actual Input - Taller hit area */}
          <input
            className="absolute inset-0 z-20 h-full w-full cursor-pointer opacity-0"
            max={VELOCITY_THRESHOLDS.NORMALIZATION_MAX + 500}
            min="0"
            onChange={(e) => setManualVelocity(Number(e.target.value))}
            type="range"
            value={velocity}
          />

          {/* Floating Thumb Hint */}
          <motion.div
            animate={{
              left: `${Math.min((velocity / VELOCITY_THRESHOLDS.NORMALIZATION_MAX) * 100, 100)}%`,
              x: "-50%",
              scale: manualVelocity !== null ? 1.2 : 0.8,
              opacity: manualVelocity !== null ? 1 : 0,
            }}
            className="pointer-events-none absolute top-1/2 z-10 h-3.5 w-3.5 -translate-y-1/2 rounded-full bg-white shadow-[0_0_15px_rgba(255,255,255,0.5)]"
            transition={{ type: "spring", damping: 25, stiffness: 300 }}
          />

          {/* Hover indicator for thumb when manual is OFF */}
          {manualVelocity === null ? (
            <div
              className="pointer-events-none absolute top-1/2 h-3 w-3 -translate-y-1/2 rounded-full border-2 border-white/20 opacity-0 transition-opacity group-hover/slider:opacity-100"
              style={{
                left: `${Math.min((velocity / VELOCITY_THRESHOLDS.NORMALIZATION_MAX) * 100, 100)}%`,
                transform: "translate(-50%, -50%)",
              }}
            />
          ) : null}
        </div>
      </div>

      <div className="h-10 w-px bg-white/10" />

      <div className="flex items-center gap-4">
        <button
          className={`rounded-xl p-2.5 transition-all duration-300 ${
            manualVelocity !== null
              ? "bg-primary text-black shadow-[0_0_20px_rgba(var(--primary-rgb),0.4)]"
              : "bg-white/5 text-zinc-400 hover:bg-white/10"
          }`}
          onClick={() =>
            setManualVelocity(manualVelocity === null ? velocity : null)
          }
          title={
            manualVelocity !== null
              ? "Switch to Auto-Scroll Velocity"
              : "Switch to Manual Override"
          }
        >
          <Settings
            className={manualVelocity !== null ? "animate-spin-slow" : ""}
            size={18}
          />
        </button>
        <div className="flex min-w-[80px] flex-col items-start">
          <div className="font-mono text-[10px] text-zinc-500 uppercase tracking-tighter">
            System Phase
          </div>
          <div
            className={`font-black text-sm uppercase leading-none tracking-tighter ${readingState === "skim" ? "text-primary" : "text-blue-400"}`}
          >
            {readingState}
          </div>
        </div>
      </div>
    </div>
  );
}

function IntelligentScroller({ children }: { children: React.ReactNode }) {
  const { readingState, lockVelocity } = useVelocityState();
  const containerRef = useRef<HTMLDivElement>(null);

  // Using a ref to track the "anchor" before the layout shift happens.
  // We update this continuously on scroll so that when readingState changes,
  // we already know what was visible and where it was.
  const lastAnchorRef = useRef<{
    index: number;
    topOffset: number;
    viewportOffset: number;
  } | null>(null);

  useEffect(() => {
    const updateAnchor = () => {
      if (!containerRef.current) {
        return;
      }

      const childrenElements = Array.from(containerRef.current.children);
      const viewportHalf = window.innerHeight * 0.4; // Target slightly above center for better "gaze" anchoring

      let closestIndex = 0;
      let minDistance = Number.POSITIVE_INFINITY;

      childrenElements.forEach((child, i) => {
        const rect = child.getBoundingClientRect();
        // We anchor to the top of the element plus a small buffer
        const distance = Math.abs(rect.top - viewportHalf);

        if (distance < minDistance) {
          minDistance = distance;
          closestIndex = i;
        }
      });

      if (childrenElements[closestIndex]) {
        const rect = childrenElements[closestIndex].getBoundingClientRect();
        lastAnchorRef.current = {
          index: closestIndex,
          topOffset: rect.top,
          viewportOffset: rect.top, // Store relative to viewport
        };
      }
    };

    window.addEventListener("scroll", updateAnchor, { passive: true });
    updateAnchor(); // Initial capture
    return () => window.removeEventListener("scroll", updateAnchor);
  }, []);

  // Apply stabilization when readingState changes
  useLayoutEffect(() => {
    if (!(lastAnchorRef.current && containerRef.current)) {
      return;
    }

    const anchor = lastAnchorRef.current;
    const childrenElements = Array.from(containerRef.current.children);
    const targetChild = childrenElements[anchor.index] as HTMLElement;

    if (!targetChild) {
      return;
    }

    // Force a synchronous layout pass for accurate measurement
    // We need to wait for the next frame or use a small delay if content is still morphing
    // but useLayoutEffect usually fires after DOM updates but before paint.

    const newRect = targetChild.getBoundingClientRect();
    const delta = newRect.top - anchor.viewportOffset;

    if (Math.abs(delta) > 0.1) {
      lockVelocity();
      window.scrollBy({ top: delta, behavior: "instant" as any });
    }
  }, [lockVelocity]);

  return (
    <main
      className="relative z-10 mx-auto max-w-3xl px-6 py-24"
      ref={containerRef}
    >
      {children}
    </main>
  );
}

export default function VelocityResponsiveDesign() {
  return (
    <VelocityProvider>
      <div className="relative min-h-screen overflow-x-hidden bg-black text-white selection:bg-primary selection:text-black">
        <SpeedLines />

        {/* Header Section */}
        <div className="relative flex h-screen flex-col items-center justify-center overflow-hidden bg-zinc-950 p-8 text-center">
          <StaticBackgroundPattern />

          <motion.div
            animate={{ opacity: 1, y: 0 }}
            className="relative z-10"
            initial={{ opacity: 0, y: 30 }}
            transition={{ duration: 1, ease: [0.16, 1, 0.3, 1] }}
          >
            <h1 className="mb-4 bg-linear-to-b from-white to-zinc-700 bg-clip-text font-black text-5xl text-transparent text-white uppercase italic leading-[0.9] tracking-tighter sm:text-8xl">
              The
              <br />
              Relativistic
              <br />
              Reader
            </h1>

            <div className="mt-16 flex flex-col items-center gap-4">
              <div className="h-24 w-px bg-linear-to-b from-primary/50 to-transparent" />
              <span className="animate-pulse font-mono text-[9px] text-zinc-600 uppercase tracking-widest">
                Scroll to Accelerate
              </span>
            </div>
          </motion.div>
        </div>

        <IntelligentScroller>
          {CONTENT.map((item, i) => {
            if (item.type === "text") {
              return (
                <VelocityText
                  detailed={item.detailed!}
                  key={i}
                  summary={item.summary!}
                />
              );
            }
            if (item.type === "image") {
              return <VelocityImage alt={item.alt!} key={i} src={item.src!} />;
            }
            if (item.type === "code") {
              return (
                <VelocityCodeBlock
                  code={item.code!}
                  filename={item.filename!}
                  key={i}
                  language={item.language!}
                />
              );
            }
            return null;
          })}
        </IntelligentScroller>

        <FlightControl />

        <footer className="relative flex h-[200vh] flex-col items-center justify-center border-white/5 border-t bg-zinc-950">
          <div className="absolute top-0 left-1/2 h-full w-px -translate-x-1/2 bg-linear-to-b from-white/10 to-transparent" />
          <p className="mb-4 font-mono text-xs text-zinc-700 uppercase tracking-[0.4em]">
            End of Content Stream
          </p>
          <div className="flex gap-4">
            <Zap className="text-zinc-800" size={14} />
            <Monitor className="text-zinc-800" size={14} />
            <Settings className="text-zinc-800" size={14} />
          </div>
        </footer>

        <div className="hidden md:block">
          <AIWidget />
        </div>
      </div>
    </VelocityProvider>
  );
}

